/**
 * dyld shared-cache parser (LDR-006, partial).
 *
 * Parses the cache header, mappings, image table, and sub-cache array for
 * v1-era arm64/arm64e caches. Synthetic fixtures are generated by this repo;
 * parsing a real Apple cache has not been verified on a licensed host, so the
 * roadmap task remains partial.
 *
 * Not implemented: slide application, cache fixups, trie lookup, ObjC/Swift
 * optimization payloads, and symbol-file pairing.
 */

import { CompatError } from "../errors.js";
import { parseMachO } from "../macho/parse.js";
import type { MachOImage } from "../macho/types.js";

export class SharedCacheError extends CompatError {
  override name = "SharedCacheError";
}

export interface CacheMapping {
  readonly address: bigint;
  readonly size: bigint;
  readonly fileOffset: bigint;
  readonly maxProtection: number;
  readonly initProtection: number;
}

export interface CacheImage {
  readonly address: bigint;
  readonly modTime: bigint;
  readonly inode: bigint;
  readonly path: string;
}

export interface CacheSubCache {
  readonly uuid: string;
  readonly cacheVMOffset: bigint;
}

export interface SharedCacheInfo {
  readonly magic: string;
  readonly mappings: readonly CacheMapping[];
  readonly images: readonly CacheImage[];
  readonly subCaches: readonly CacheSubCache[];
  readonly sharedRegionStart: bigint;
  readonly sharedRegionSize: bigint;
  readonly maxSlide: bigint;
}

const HEADER_MIN = 72;
const MAX_MAPPINGS = 4096;
const MAX_IMAGES = 200_000;
const MAX_SUBCACHES = 64;

/** Apply a valid slide to mappings and image addresses (LDR-007). */
export function applyCacheSlide(cache: SharedCacheInfo, slide: bigint): SharedCacheInfo {
  if (slide < 0n || slide > cache.maxSlide) {
    throw new SharedCacheError(
      "cache_bad_slide",
      `slide 0x${slide.toString(16)} exceeds max 0x${cache.maxSlide.toString(16)}`,
    );
  }
  if (slide % 0x1000n !== 0n) {
    throw new SharedCacheError("cache_bad_slide", "slide must be page-aligned");
  }
  return {
    ...cache,
    mappings: cache.mappings.map((mapping) => ({ ...mapping, address: mapping.address + slide })),
    images: cache.images.map((image) => ({ ...image, address: image.address + slide })),
  };
}

/** Find the sub-cache whose VM offset is nearest at or below a cache address. */
export function subCacheForAddress(cache: SharedCacheInfo, address: bigint): CacheSubCache | null {
  let best: CacheSubCache | null = null;
  for (const sub of cache.subCaches) {
    if (sub.cacheVMOffset <= address && (!best || sub.cacheVMOffset > best.cacheVMOffset))
      best = sub;
  }
  return best;
}

export function imageAtAddress(cache: SharedCacheInfo, address: bigint): CacheImage | null {
  for (const image of cache.images) if (image.address === address) return image;
  return null;
}

export function imageForPath(cache: SharedCacheInfo, path: string): CacheImage | null {
  return cache.images.find((image) => image.path === path) ?? null;
}

/** Images belonging to a sub-cache, using its VM offset as the lower bound. */
export function imagesForSubCache(cache: SharedCacheInfo, subCache: CacheSubCache): CacheImage[] {
  const ordered = [...cache.subCaches].sort((a, b) => (a.cacheVMOffset < b.cacheVMOffset ? -1 : 1));
  const index = ordered.findIndex((entry) => entry.uuid === subCache.uuid);
  const next = index >= 0 ? ordered[index + 1] : undefined;
  return cache.images.filter(
    (image) =>
      image.address >= subCache.cacheVMOffset &&
      (next === undefined || image.address < next.cacheVMOffset),
  );
}

/**
 * Extract the Mach-O bytes for a cache image. The synthetic cache builder
 * places the image 0x1000 bytes into its mapping.
 */
export function cacheImageBytes(
  cache: SharedCacheInfo,
  cacheBytes: Uint8Array,
  path: string,
): { bytes: Uint8Array; image: CacheImage; macho: MachOImage } {
  const image = imageForPath(cache, path);
  if (!image) throw new SharedCacheError("cache_image_missing", `cache has no image ${path}`);
  let mapping: CacheMapping | null = null;
  for (const candidate of cache.mappings) {
    if (image.address >= candidate.address && image.address < candidate.address + candidate.size) {
      mapping = candidate;
      break;
    }
  }
  if (!mapping) {
    throw new SharedCacheError(
      "cache_image_unmapped",
      `${path} at 0x${image.address.toString(16)} is not mapped`,
    );
  }
  const offset = Number(mapping.fileOffset + (image.address - mapping.address));
  if (offset < 0 || offset >= cacheBytes.length) {
    throw new SharedCacheError(
      "cache_image_out_of_bounds",
      `${path} file offset ${offset} is outside the cache`,
    );
  }
  const slice = cacheBytes.subarray(offset);
  const macho = parseMachO(slice).image;
  return { bytes: slice.subarray(0, macho.byteLength), image, macho };
}

/** Resolve one exported symbol from a cache image (synthetic caches). */
export function cacheSymbol(
  cache: SharedCacheInfo,
  cacheBytes: Uint8Array,
  path: string,
  symbol: string,
): bigint | null {
  const { image, macho } = cacheImageBytes(cache, cacheBytes, path);
  const exported = macho.exportsTrie?.exports.get(symbol);
  if (exported && exported.address !== null && exported.kind !== "reexport") {
    return exported.kind === "absolute"
      ? BigInt(exported.address)
      : image.address + BigInt(exported.address);
  }
  const found = macho.symbols.find(
    (entry) => entry.name === symbol && !entry.debug && !entry.undefined && entry.external,
  );
  if (!found) return null;
  return image.address + BigInt(found.value - macho.preferredBase);
}

/** Build a synthetic cache embedding one generated Mach-O image. */
export function buildSyntheticCacheWithImage(
  path: string,
  machoBytes: Uint8Array,
  options: { start?: bigint } = {},
): Uint8Array {
  const start = options.start ?? 0x180000000n;
  const headerSize = 0x400;
  const mappingOffset = headerSize;
  const imagesOffset = mappingOffset + 32;
  const subOffset = imagesOffset + 32;
  const pathStart = subOffset;
  const pathBytes = new TextEncoder().encode(`${path}\0`);
  const dataStart = Math.ceil((pathStart + pathBytes.length) / 0x1000) * 0x1000;
  const imageOffset = 0x1000;
  const total = dataStart + imageOffset + machoBytes.length;
  const bytes = new Uint8Array(total);
  const view = new DataView(bytes.buffer);
  bytes.set(new TextEncoder().encode("dyld_v1  arm64e").subarray(0, 16), 0);
  view.setUint32(16, mappingOffset, true);
  view.setUint32(20, 1, true);
  view.setUint32(24, imagesOffset, true);
  view.setUint32(28, 1, true);
  view.setBigUint64(48, start, true);
  view.setBigUint64(56, BigInt(imageOffset + machoBytes.length), true);
  view.setBigUint64(64, 0x1_0000_0000n, true);
  view.setUint32(188, 0, true);
  view.setUint32(192, 0, true);
  view.setBigUint64(mappingOffset, start, true);
  view.setBigUint64(mappingOffset + 8, BigInt(imageOffset + machoBytes.length), true);
  view.setBigUint64(mappingOffset + 16, BigInt(dataStart), true);
  view.setUint32(mappingOffset + 24, 5, true);
  view.setUint32(mappingOffset + 28, 5, true);
  view.setBigUint64(imagesOffset, start + BigInt(imageOffset), true);
  view.setBigUint64(imagesOffset + 8, 0n, true);
  view.setBigUint64(imagesOffset + 16, 1n, true);
  view.setUint32(imagesOffset + 24, pathStart, true);
  bytes.set(pathBytes, pathStart);
  bytes.set(machoBytes, dataStart + imageOffset);
  return bytes;
}

export function parseSharedCache(bytes: Uint8Array): SharedCacheInfo {
  if (bytes.length < HEADER_MIN) {
    throw new SharedCacheError(
      "cache_truncated",
      `cache is ${bytes.length} bytes, need ${HEADER_MIN}`,
    );
  }
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const magic = new TextDecoder().decode(bytes.subarray(0, 16)).replace(/\0+$/, "").trimEnd();
  if (!magic.startsWith("dyld_v1")) {
    throw new SharedCacheError("bad_cache_magic", `expected dyld_v1 magic, got "${magic}"`);
  }
  const mappingOffset = view.getUint32(16, true);
  const mappingCount = view.getUint32(20, true);
  const imagesOffset = view.getUint32(24, true);
  const imagesCount = view.getUint32(28, true);
  const sharedRegionStart = view.getBigUint64(48, true);
  const sharedRegionSize = view.getBigUint64(56, true);
  const maxSlide = view.getBigUint64(64, true);

  if (mappingCount > MAX_MAPPINGS || imagesCount > MAX_IMAGES) {
    throw new SharedCacheError(
      "cache_bad_count",
      `implausible cache counts ${mappingCount}/${imagesCount}`,
    );
  }
  checkRange(bytes.length, mappingOffset, mappingCount * 32, "mappings");
  checkRange(bytes.length, imagesOffset, imagesCount * 32, "images");

  const mappings: CacheMapping[] = [];
  for (let index = 0; index < mappingCount; index += 1) {
    const at = mappingOffset + index * 32;
    mappings.push({
      address: view.getBigUint64(at, true),
      size: view.getBigUint64(at + 8, true),
      fileOffset: view.getBigUint64(at + 16, true),
      maxProtection: view.getUint32(at + 24, true),
      initProtection: view.getUint32(at + 28, true),
    });
  }

  const images: CacheImage[] = [];
  for (let index = 0; index < imagesCount; index += 1) {
    const at = imagesOffset + index * 32;
    const pathOffset = view.getUint32(at + 24, true);
    images.push({
      address: view.getBigUint64(at, true),
      modTime: view.getBigUint64(at + 8, true),
      inode: view.getBigUint64(at + 16, true),
      path: cstring(bytes, pathOffset, `image ${index} path`),
    });
  }

  const subCaches: CacheSubCache[] = [];
  if (bytes.length >= 200) {
    const subOffset = view.getUint32(188, true);
    const subCount = view.getUint32(192, true);
    if (subCount > MAX_SUBCACHES) {
      throw new SharedCacheError("cache_bad_count", `implausible sub-cache count ${subCount}`);
    }
    if (subOffset !== 0 && subCount !== 0) {
      checkRange(bytes.length, subOffset, subCount * 24, "sub-caches");
      for (let index = 0; index < subCount; index += 1) {
        const at = subOffset + index * 24;
        subCaches.push({
          uuid: uuid(bytes.subarray(at, at + 16)),
          cacheVMOffset: view.getBigUint64(at + 16, true),
        });
      }
    }
  }

  return {
    magic,
    mappings,
    images,
    subCaches,
    sharedRegionStart,
    sharedRegionSize,
    maxSlide,
  };
}

export interface BuildSharedCacheOptions {
  readonly magic?: string;
  readonly sharedRegionStart?: bigint;
  readonly sharedRegionSize?: bigint;
  readonly maxSlide?: bigint;
  readonly mappings?: readonly Omit<CacheMapping, "fileOffset">[];
  readonly images?: readonly Omit<CacheImage, "path">[];
  readonly imagePaths?: readonly string[];
  readonly subCaches?: readonly CacheSubCache[];
}

/** Build a synthetic cache fixture; never contains Apple bytes. */
export function buildSyntheticSharedCache(options: BuildSharedCacheOptions = {}): Uint8Array {
  const magic = options.magic ?? "dyld_v1  arm64e";
  const mappings = options.mappings ?? [
    { address: 0x180000000n, size: 0x4000n, maxProtection: 5, initProtection: 5 },
  ];
  const images = options.images ?? [{ address: 0x180001000n, modTime: 0n, inode: 1n }];
  const paths =
    options.imagePaths ?? images.map((_image, index) => `/usr/lib/libSystem${index}.dylib`);
  const subCaches = options.subCaches ?? [];
  const headerSize = 0x400;
  const mappingOffset = headerSize;
  const imagesOffset = mappingOffset + mappings.length * 32;
  const subOffset = imagesOffset + images.length * 32;
  const pathStart = subOffset + subCaches.length * 24;
  const pathBytes = new TextEncoder().encode(paths.map((path) => `${path}\0`).join(""));
  const total = pathStart + pathBytes.length;
  const bytes = new Uint8Array(total);
  const view = new DataView(bytes.buffer);
  const magicBytes = new TextEncoder().encode(magic);
  bytes.set(magicBytes.subarray(0, 16), 0);
  view.setUint32(16, mappingOffset, true);
  view.setUint32(20, mappings.length, true);
  view.setUint32(24, imagesOffset, true);
  view.setUint32(28, images.length, true);
  view.setBigUint64(48, options.sharedRegionStart ?? 0x180000000n, true);
  view.setBigUint64(56, options.sharedRegionSize ?? 0x4000n, true);
  view.setBigUint64(64, options.maxSlide ?? 0x1_0000_0000n, true);
  if (bytes.length >= 200) {
    view.setUint32(188, subCaches.length > 0 ? subOffset : 0, true);
    view.setUint32(192, subCaches.length, true);
  }
  mappings.forEach((mapping, index) => {
    const at = mappingOffset + index * 32;
    view.setBigUint64(at, mapping.address, true);
    view.setBigUint64(at + 8, mapping.size, true);
    view.setBigUint64(at + 16, BigInt(mappingOffset), true);
    view.setUint32(at + 24, mapping.maxProtection, true);
    view.setUint32(at + 28, mapping.initProtection, true);
  });
  images.forEach((image, index) => {
    const at = imagesOffset + index * 32;
    view.setBigUint64(at, image.address, true);
    view.setBigUint64(at + 8, image.modTime, true);
    view.setBigUint64(at + 16, image.inode, true);
    view.setUint32(at + 24, pathStart + pathOffsets(paths, index), true);
  });
  subCaches.forEach((subCache, index) => {
    const at = subOffset + index * 24;
    bytes.set(parseUuid(subCache.uuid), at);
    view.setBigUint64(at + 16, subCache.cacheVMOffset, true);
  });
  bytes.set(pathBytes, pathStart);
  return bytes;
}

function checkRange(length: number, offset: number, size: number, label: string): void {
  if (offset < 0 || size < 0 || offset + size > length) {
    throw new SharedCacheError(
      "cache_out_of_bounds",
      `${label} [${offset}, ${offset + size}) exceeds ${length}`,
    );
  }
}

function cstring(bytes: Uint8Array, offset: number, label: string): string {
  if (offset < 0 || offset >= bytes.length) {
    throw new SharedCacheError("cache_out_of_bounds", `${label} starts outside the cache`);
  }
  let end = offset;
  while (end < bytes.length && bytes[end] !== 0) end += 1;
  if (end >= bytes.length) throw new SharedCacheError("cache_bad_path", `${label} is unterminated`);
  return new TextDecoder().decode(bytes.subarray(offset, end));
}

function uuid(bytes: Uint8Array): string {
  const hex = [...bytes].map((byte) => byte.toString(16).padStart(2, "0")).join("");
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

function parseUuid(value: string): Uint8Array {
  const hex = value.replaceAll("-", "");
  if (!/^[0-9a-f]{32}$/i.test(hex)) throw new SharedCacheError("bad_uuid", `invalid UUID ${value}`);
  return Uint8Array.from({ length: 16 }, (_entry, index) =>
    Number.parseInt(hex.slice(index * 2, index * 2 + 2), 16),
  );
}

function pathOffsets(paths: readonly string[], index: number): number {
  let offset = 0;
  for (let cursor = 0; cursor < index; cursor += 1)
    offset += new TextEncoder().encode(`${paths[cursor]}\0`).length;
  return offset;
}
